import{_ as s,l as i,o as e,c as o,v as t,p as l,x as r,d as p,i as d,S as E}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"生成树","description":"","frontmatter":{"title":"生成树","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/spanning-tree.md","filePath":"cs/spanning-tree.md","lastUpdated":1789023840000}'),c={name:"cs/spanning-tree.md"};function A(h,a,P,m,B,_){const n=i("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="生成树" tabindex="-1">生成树 <a class="header-anchor" href="#生成树" aria-label="Permalink to &quot;生成树&quot;">​</a></h1><div class="epigraph"><p>冗余链路形成环时，广播与未知单播会绕圈放大；生成树先关掉一些端口，留下无环转发拓扑。</p><footer>—— 据 Perlman, An Algorithm for Distributed Computation of a Spanning Tree in an Extended LAN, 1985；IEEE 802.1D 整理</footer></div><p><a href="/cs/vlan">上一课</a>让交换机对未知帧泛洪。两条交换机之间若有两条链路，泛洪帧会永转，MAC 表抖动。缺口不是再学一遍源地址，而是在链路层算一棵<strong>生成树</strong>，阻塞冗余端口。图算法课的<a href="/cs/mst-kruskal-prim">最小生成树</a>给过边权树；这里权是桥优先级与端口代价，目标先是无环连通。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>物理环提供容错，逻辑必须无环。Perlman 的分布式算法：选根桥，每桥选根端口，每网段选指定端口，其余阻塞。BPDU 在桥之间交换。缺口是这套选举，不是 IP 的最短路径——生成树甚至不优化应用延迟，只保证二层可泛洪。</p><p>本课不把 RSTP 的握手时序写到状态机每一行。</p><p><span class="marginnote">阻塞端口仍听 BPDU，以便根失败时恢复。数据平面不转发，控制平面活着。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>比较桥 ID（优先级 + MAC）最小者为根。根代价沿 BPDU 传播。指定端口是该网段上根代价最好的桥的端口。收敛期间端口可处于学习/监听，避免临时环。VLAN 可每 VLAN 一棵树（PVST 等），主干只要求：有环必须先成树再按上一课转发。</p>',9)),(e(),l(E,null,{default:r(()=>[d(n,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20RING%5B%22%E5%86%97%E4%BD%99%E9%93%BE%E8%B7%AF%22%5D%20--%3E%20BPDU%5B%22%E4%BA%A4%E6%8D%A2%20BPDU%22%5D%0A%20%20BPDU%20--%3E%20ROOT%5B%22%E9%80%89%E6%A0%B9%22%5D%0A%20%20ROOT%20--%3E%20BLK%5B%22%E9%98%BB%E5%A1%9E%E9%9D%9E%E6%A0%91%E7%AB%AF%E5%8F%A3%22%5D%0A%20%20BLK%20--%3E%20FWD%5B%22%E6%97%A0%E7%8E%AF%E6%B3%9B%E6%B4%AA%E4%B8%8E%E5%AD%A6%E4%B9%A0%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>生成树把二层以太网限制成树，于是<a href="/cs/csma-switch">交换机</a>的泛洪有终止。代价是：有的链路闲置，带宽浪费；根附近成为瓶颈。这正是后课要用三层路由、等价多路径的动机之一，本课不提前 BGP。与端到端：树断了会黑一阵，主机 TCP 自己重传——下层「几乎连通」仍不是文件保证。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 TRILL、SPB、EVPN 当默认校园网，不引入最短路径二层的全部控制平面。也不把生成树根劫持写成攻击步骤。无线 mesh 与有线桥不是同一算法。</p><p>根桥选举若被更小优先级抢占，树会 reconverge，转发暂停。优先级是管理配置，不是 MAC 自动最优。</p><p>RSTP 用提议/同意加速，对象仍是一棵无环活动拓扑。</p><p>后课默认：同一广播域在树上看是无环的。跨网还缺「哪一跳的 MAC 对应哪个 IP」，下一课 ARP。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>二层环 + 泛洪 = 风暴；生成树阻塞冗余。</li><li>选根、根端口、指定端口；BPDU 传播。</li><li>IP 与 ARP 还没有：下一课在已连通的链路上解析地址。</li><li>出处：Perlman, 1985；IEEE 802.1D；Kurose and Ross。</li></ul>',9))])}const f=s(c,[["render",A]]);export{D as __pageData,f as default};
